//! Deterministic GGUF fixture builder.
//!
//! This module is compiled under `cfg(test)` and under the `testing` feature.
//! It exists so that the committed test fixtures under
//! `tests/fixtures/*.gguf` can be regenerated byte-for-byte and so that tests
//! can build small malformed files without hand-writing GGUFs.
//!
//! Presets:
//!
//! * [`minimal`] -- version 3, no metadata, no tensors, 32 bytes of zeros
//!   after the 24-byte header;
//! * [`rich`] -- version 3, 24 metadata entries covering all 13 value types
//!   (including nested arrays), split metadata, and three tensors (`F32`
//!   `[64, 512]`, `Q8_0` `[32, 4]`, `Q4_K` `[256, 2]`) at aligned offsets.
//!
//! Regenerate the committed fixtures with:
//!
//! ```sh
//! UPDATE_FIXTURES=1 cargo test -p hoard-gguf --features testing --test generate
//! ```

use crate::header::MAGIC;
use crate::metadata::ValueType;
use crate::quant;

/// Builder layout alignment cap: keeps accidental fixtures from allocating
/// absurd padding when an unusual `general.alignment` is under test.
const MAX_LAYOUT_ALIGNMENT: u32 = 64 * 1024;

/// Builder data-section cap: keeps accidental fixtures from allocating absurd
/// amounts of zero bytes when dimensions are huge.
const MAX_LAYOUT_DATA_BYTES: usize = 1 << 24;

/// A metadata value the fixture builder can encode.
#[derive(Debug, Clone, PartialEq)]
pub enum Value {
    /// Unsigned 8-bit integer.
    U8(u8),
    /// Signed 8-bit integer.
    I8(i8),
    /// Unsigned 16-bit integer.
    U16(u16),
    /// Signed 16-bit integer.
    I16(i16),
    /// Unsigned 32-bit integer.
    U32(u32),
    /// Signed 32-bit integer.
    I32(i32),
    /// 32-bit float.
    F32(f32),
    /// Boolean.
    Bool(bool),
    /// UTF-8 string.
    String(String),
    /// Array of the given element type.
    Array(ValueType, Vec<Value>),
    /// Unsigned 64-bit integer.
    U64(u64),
    /// Signed 64-bit integer.
    I64(i64),
    /// 64-bit float.
    F64(f64),
}

impl Value {
    /// The metadata value type id this value encodes.
    #[must_use]
    pub fn type_id(&self) -> u32 {
        match self {
            Self::U8(_) => ValueType::U8.id(),
            Self::I8(_) => ValueType::I8.id(),
            Self::U16(_) => ValueType::U16.id(),
            Self::I16(_) => ValueType::I16.id(),
            Self::U32(_) => ValueType::U32.id(),
            Self::I32(_) => ValueType::I32.id(),
            Self::F32(_) => ValueType::F32.id(),
            Self::Bool(_) => ValueType::Bool.id(),
            Self::String(_) => ValueType::String.id(),
            Self::Array(_, _) => ValueType::Array.id(),
            Self::U64(_) => ValueType::U64.id(),
            Self::I64(_) => ValueType::I64.id(),
            Self::F64(_) => ValueType::F64.id(),
        }
    }

    /// Encode the value payload (the bytes after the value type id).
    #[must_use]
    pub fn encode(&self) -> Vec<u8> {
        let mut out = Vec::new();
        self.encode_into(&mut out);
        out
    }

    fn encode_into(&self, out: &mut Vec<u8>) {
        match self {
            Self::U8(value) => out.push(*value),
            Self::I8(value) => out.push(*value as u8),
            Self::U16(value) => out.extend_from_slice(&value.to_le_bytes()),
            Self::I16(value) => out.extend_from_slice(&value.to_le_bytes()),
            Self::U32(value) => out.extend_from_slice(&value.to_le_bytes()),
            Self::I32(value) => out.extend_from_slice(&value.to_le_bytes()),
            Self::F32(value) => out.extend_from_slice(&value.to_le_bytes()),
            Self::Bool(value) => out.push(u8::from(*value)),
            Self::String(value) => encode_string(out, value),
            Self::Array(element_type, values) => {
                out.extend_from_slice(&element_type.id().to_le_bytes());
                out.extend_from_slice(&(values.len() as u64).to_le_bytes());
                for value in values {
                    value.encode_into(out);
                }
            }
            Self::U64(value) => out.extend_from_slice(&value.to_le_bytes()),
            Self::I64(value) => out.extend_from_slice(&value.to_le_bytes()),
            Self::F64(value) => out.extend_from_slice(&value.to_le_bytes()),
        }
    }
}

/// A tensor to encode into a fixture.
#[derive(Debug, Clone)]
pub struct TensorSpec {
    /// Tensor name.
    pub name: String,
    /// Dimensions, innermost first.
    pub dims: Vec<u64>,
    /// Numeric `ggml_type` id.
    pub type_id: u32,
    /// Data length in bytes; `None` computes the size from the quantization
    /// table (0 for unknown types).
    pub data_len: Option<usize>,
    /// Data offset relative to the start of the data section; `None` places the
    /// tensor contiguously after the previous one, aligned to the layout
    /// alignment.
    pub offset: Option<u64>,
}

impl TensorSpec {
    /// Create a tensor whose data size is derived from its quantization type.
    #[must_use]
    pub fn new(name: &str, dims: &[u64], type_id: u32) -> Self {
        Self {
            name: name.to_owned(),
            dims: dims.to_vec(),
            type_id,
            data_len: None,
            offset: None,
        }
    }

    /// Override the number of zero data bytes written for this tensor.
    #[must_use]
    pub fn data_len(mut self, data_len: usize) -> Self {
        self.data_len = Some(data_len);
        self
    }

    /// Override the data offset (relative to the start of the data section).
    #[must_use]
    pub fn offset(mut self, offset: u64) -> Self {
        self.offset = Some(offset);
        self
    }
}

/// A deterministic GGUF byte builder.
#[derive(Debug, Clone)]
pub struct Builder {
    magic: [u8; 4],
    version: u32,
    metadata: Vec<(String, u32, Vec<u8>)>,
    tensors: Vec<TensorSpec>,
    declared_tensor_count: Option<u64>,
    declared_metadata_count: Option<u64>,
    data_section_len: Option<usize>,
    trailing: Vec<u8>,
}

impl Default for Builder {
    fn default() -> Self {
        Self::new()
    }
}

impl Builder {
    /// Start a version 3 fixture with no metadata and no tensors.
    #[must_use]
    pub fn new() -> Self {
        Self {
            magic: MAGIC,
            version: 3,
            metadata: Vec::new(),
            tensors: Vec::new(),
            declared_tensor_count: None,
            declared_metadata_count: None,
            data_section_len: None,
            trailing: Vec::new(),
        }
    }

    /// Override the GGUF version word.
    #[must_use]
    pub fn version(mut self, version: u32) -> Self {
        self.version = version;
        self
    }

    /// Override the magic bytes.
    #[must_use]
    pub fn magic(mut self, magic: [u8; 4]) -> Self {
        self.magic = magic;
        self
    }

    /// Append a typed metadata entry.
    #[must_use]
    pub fn metadata(mut self, key: &str, value: Value) -> Self {
        let type_id = value.type_id();
        let payload = value.encode();
        self.metadata.push((key.to_owned(), type_id, payload));
        self
    }

    /// Append a metadata entry with a raw payload (for malformed fixtures).
    #[must_use]
    pub fn metadata_raw(mut self, key: &str, type_id: u32, payload: Vec<u8>) -> Self {
        self.metadata.push((key.to_owned(), type_id, payload));
        self
    }

    /// Append a tensor.
    #[must_use]
    pub fn tensor(mut self, spec: TensorSpec) -> Self {
        self.tensors.push(spec);
        self
    }

    /// Override the tensor count written in the header.
    #[must_use]
    pub fn declared_tensor_count(mut self, count: u64) -> Self {
        self.declared_tensor_count = Some(count);
        self
    }

    /// Override the metadata count written in the header.
    #[must_use]
    pub fn declared_metadata_count(mut self, count: u64) -> Self {
        self.declared_metadata_count = Some(count);
        self
    }

    /// Override the length of the zero-filled data section.
    #[must_use]
    pub fn data_section_len(mut self, len: usize) -> Self {
        self.data_section_len = Some(len);
        self
    }

    /// Append bytes after the last tensor.
    #[must_use]
    pub fn trailing(mut self, bytes: &[u8]) -> Self {
        self.trailing.extend_from_slice(bytes);
        self
    }

    fn layout_alignment(&self) -> u32 {
        for (key, type_id, payload) in &self.metadata {
            if key == crate::file::GENERAL_ALIGNMENT_KEY
                && *type_id == ValueType::U32.id()
                && payload.len() >= 4
            {
                let mut bytes = [0_u8; 4];
                bytes.copy_from_slice(&payload[..4]);
                let alignment = u32::from_le_bytes(bytes);
                if alignment == 0 {
                    return crate::header::DEFAULT_ALIGNMENT;
                }
                return alignment.min(MAX_LAYOUT_ALIGNMENT);
            }
        }
        crate::header::DEFAULT_ALIGNMENT
    }

    /// Encode the fixture.
    #[must_use]
    pub fn build(self) -> Vec<u8> {
        let alignment = u64::from(self.layout_alignment());
        let mut out = Vec::new();
        out.extend_from_slice(&self.magic);
        out.extend_from_slice(&self.version.to_le_bytes());
        out.extend_from_slice(
            &self
                .declared_tensor_count
                .unwrap_or(self.tensors.len() as u64)
                .to_le_bytes(),
        );
        out.extend_from_slice(
            &self
                .declared_metadata_count
                .unwrap_or(self.metadata.len() as u64)
                .to_le_bytes(),
        );

        for (key, type_id, payload) in &self.metadata {
            encode_string(&mut out, key);
            out.extend_from_slice(&type_id.to_le_bytes());
            out.extend_from_slice(payload);
        }

        let mut layout: Vec<(u64, usize)> = Vec::with_capacity(self.tensors.len());
        let mut current = 0_u64;
        for spec in &self.tensors {
            let data_len = spec
                .data_len
                .unwrap_or_else(|| default_data_len(spec))
                .min(MAX_LAYOUT_DATA_BYTES);
            let offset = spec.offset.unwrap_or_else(|| align_up(current, alignment));
            layout.push((offset, data_len));
            current = offset.saturating_add(data_len as u64);
        }
        for (spec, (offset, _)) in self.tensors.iter().zip(&layout) {
            encode_string(&mut out, &spec.name);
            out.extend_from_slice(&(spec.dims.len() as u32).to_le_bytes());
            for dim in &spec.dims {
                out.extend_from_slice(&dim.to_le_bytes());
            }
            out.extend_from_slice(&spec.type_id.to_le_bytes());
            out.extend_from_slice(&offset.to_le_bytes());
        }

        let data_start = align_up(out.len() as u64, alignment);
        out.resize(data_start as usize, 0);
        let data_len = self.data_section_len.unwrap_or_else(|| {
            layout
                .iter()
                .map(|(offset, len)| offset.saturating_add(*len as u64))
                .max()
                .unwrap_or(0)
                .min(MAX_LAYOUT_DATA_BYTES as u64) as usize
        });
        out.resize(out.len().saturating_add(data_len), 0);
        out.extend_from_slice(&self.trailing);
        out
    }
}

fn default_data_len(spec: &TensorSpec) -> usize {
    let Some(quant_type) = quant::from_id(spec.type_id) else {
        return 0;
    };
    let elements = spec
        .dims
        .iter()
        .try_fold(1_u64, |product, dim| product.checked_mul(*dim))
        .unwrap_or(0);
    let bytes = (elements / u64::from(quant_type.block_size))
        .saturating_mul(u64::from(quant_type.type_size));
    usize::try_from(bytes).unwrap_or(0)
}

fn align_up(value: u64, alignment: u64) -> u64 {
    if alignment == 0 {
        return value;
    }
    let remainder = value % alignment;
    if remainder == 0 {
        value
    } else {
        value.saturating_add(alignment - remainder)
    }
}

fn encode_string(out: &mut Vec<u8>, value: &str) {
    out.extend_from_slice(&(value.len() as u64).to_le_bytes());
    out.extend_from_slice(value.as_bytes());
}

/// Build the `synthetic-minimal.gguf` fixture: version 3, no metadata, no
/// tensors, exactly 32 bytes long (24-byte header plus 8 zero padding bytes).
#[must_use]
pub fn minimal() -> Vec<u8> {
    Builder::new().build()
}

/// Build the `synthetic-rich.gguf` fixture.
///
/// Version 3 with `general.alignment` 64, all 13 metadata value types
/// (including `array<string>` of length 5, `array<f32>`, `array<i32>`,
/// `array<u32>`, and one nested array), complete split metadata
/// (`split.no` 1 of `split.count` 2, `split.tensors.count` 48), and three
/// tensors at aligned offsets: `F32 [64, 512]`, `Q8_0 [32, 4]`, and
/// `Q4_K [256, 2]`. The file ends exactly at the end of the last tensor.
#[must_use]
pub fn rich() -> Vec<u8> {
    Builder::new()
        // General model metadata.
        .metadata(
            crate::file::GENERAL_ARCHITECTURE_KEY,
            Value::String("llama".into()),
        )
        .metadata(
            crate::file::GENERAL_NAME_KEY,
            Value::String("synthetic-rich".into()),
        )
        .metadata(crate::file::GENERAL_QUANTIZATION_VERSION_KEY, Value::U32(2))
        .metadata(crate::file::GENERAL_ALIGNMENT_KEY, Value::U32(64))
        // Split metadata.
        .metadata("split.no", Value::U16(1))
        .metadata("split.count", Value::U16(2))
        .metadata("split.tensors.count", Value::I32(48))
        // One entry per scalar metadata value type.
        .metadata("test.u8", Value::U8(200))
        .metadata("test.i8", Value::I8(-100))
        .metadata("test.u16", Value::U16(50_000))
        .metadata("test.i16", Value::I16(-20_000))
        .metadata("test.u32", Value::U32(3_000_000_000))
        .metadata("test.i32", Value::I32(-2_000_000_000))
        .metadata("test.f32", Value::F32(0.5))
        .metadata("test.bool", Value::Bool(true))
        .metadata("test.string", Value::String("hello".into()))
        .metadata("test.u64", Value::U64(u64::MAX - 15))
        .metadata("test.i64", Value::I64(i64::MIN))
        .metadata("test.f64", Value::F64(-2.5))
        // Arrays, including one nested array.
        .metadata(
            "test.array.string",
            Value::Array(
                ValueType::String,
                ["a", "bb", "ccc", "dddd", "eeeee"]
                    .into_iter()
                    .map(|value| Value::String(value.into()))
                    .collect(),
            ),
        )
        .metadata(
            "test.array.f32",
            Value::Array(
                ValueType::F32,
                vec![Value::F32(1.5), Value::F32(-2.5), Value::F32(3.5)],
            ),
        )
        .metadata(
            "test.array.i32",
            Value::Array(
                ValueType::I32,
                vec![Value::I32(-1), Value::I32(0), Value::I32(1)],
            ),
        )
        .metadata(
            "test.array.u32",
            Value::Array(
                ValueType::U32,
                vec![Value::U32(10), Value::U32(20), Value::U32(30)],
            ),
        )
        .metadata(
            "test.array.nested",
            Value::Array(
                ValueType::Array,
                vec![
                    Value::Array(ValueType::U8, vec![Value::U8(1), Value::U8(2)]),
                    Value::Array(ValueType::U8, vec![Value::U8(3)]),
                ],
            ),
        )
        // Three tensors with valid quantization geometry and aligned offsets.
        .tensor(TensorSpec::new("token_embd.weight", &[64, 512], 0))
        .tensor(TensorSpec::new("blk.0.attn_q.weight", &[32, 4], 8))
        .tensor(TensorSpec::new("blk.0.ffn_down.weight", &[256, 2], 12))
        .build()
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::Gguf;

    #[test]
    fn minimal_fixture_is_exactly_32_zero_padded_bytes() {
        let bytes = minimal();
        assert_eq!(bytes.len(), 32);
        assert_eq!(&bytes[..4], b"GGUF");
        assert_eq!(u32::from_le_bytes(bytes[4..8].try_into().unwrap()), 3);
        assert_eq!(u64::from_le_bytes(bytes[8..16].try_into().unwrap()), 0);
        assert_eq!(u64::from_le_bytes(bytes[16..24].try_into().unwrap()), 0);
        assert_eq!(bytes[24..], [0_u8; 8]);
    }

    #[test]
    fn fixtures_are_deterministic() {
        assert_eq!(minimal(), minimal());
        assert_eq!(rich(), rich());
    }

    #[test]
    fn rich_fixture_parses_as_expected() {
        let bytes = rich();
        let gguf = Gguf::parse(&bytes).unwrap();
        assert_eq!(gguf.header().version, 3);
        assert_eq!(gguf.metadata().len(), 24);
        assert_eq!(gguf.tensors().len(), 3);
        assert_eq!(gguf.alignment(), 64);
        assert!(gguf.warnings().is_empty(), "{:?}", gguf.warnings());
        assert_eq!(gguf.tensor_bytes().tensor_bytes, 131_496);
        assert_eq!(gguf.data_start() % 64, 0);
        // The file ends exactly at the end of the last tensor.
        let last = gguf
            .tensors()
            .iter()
            .map(|tensor| tensor.file_offset() + tensor.bytes().unwrap())
            .max()
            .unwrap();
        assert_eq!(last, bytes.len() as u64);
        // 56 bytes of alignment padding between Q8_0 and Q4_K.
        let q8 = gguf.tensor("blk.0.attn_q.weight").unwrap();
        let q4 = gguf.tensor("blk.0.ffn_down.weight").unwrap();
        assert_eq!(q4.offset() - (q8.offset() + q8.bytes().unwrap()), 56);
    }

    #[test]
    fn builder_can_override_offsets_and_sizes() {
        let bytes = Builder::new()
            .tensor(TensorSpec::new("a", &[4], 0).data_len(16).offset(64))
            .tensor(TensorSpec::new("b", &[4], 0).data_len(16).offset(128))
            .build();
        let gguf = Gguf::parse(&bytes).unwrap();
        assert_eq!(gguf.tensors()[0].offset(), 64);
        assert_eq!(gguf.tensors()[1].offset(), 128);
        assert_eq!(gguf.tensors()[0].file_offset(), gguf.data_start() + 64);
    }

    #[test]
    fn builder_writes_declared_counts_verbatim() {
        let bytes = Builder::new()
            .declared_tensor_count(0)
            .declared_metadata_count(0)
            .build();
        assert_eq!(bytes.len(), 32);
    }

    #[test]
    fn builder_aligns_data_start_and_supports_trailing_bytes() {
        let bytes = Builder::new()
            .metadata(crate::file::GENERAL_ALIGNMENT_KEY, Value::U32(16))
            .metadata("k", Value::U32(1))
            .trailing(b"tail")
            .build();
        let gguf = Gguf::parse(&bytes).unwrap();
        assert_eq!(gguf.data_start() % 16, 0);
        assert_eq!(gguf.len(), bytes.len() as u64);
        assert!(bytes.ends_with(b"tail"));
    }

    #[test]
    fn all_value_types_encode_and_round_trip() {
        let bytes = Builder::new()
            .metadata("u8", Value::U8(1))
            .metadata("i8", Value::I8(-1))
            .metadata("u16", Value::U16(2))
            .metadata("i16", Value::I16(-2))
            .metadata("u32", Value::U32(3))
            .metadata("i32", Value::I32(-3))
            .metadata("f32", Value::F32(0.5))
            .metadata("bool", Value::Bool(true))
            .metadata("string", Value::String("s".into()))
            .metadata(
                "array",
                Value::Array(ValueType::U16, vec![Value::U16(7), Value::U16(8)]),
            )
            .metadata("u64", Value::U64(4))
            .metadata("i64", Value::I64(-4))
            .metadata("f64", Value::F64(-0.25))
            .metadata(
                "nested",
                Value::Array(
                    ValueType::Array,
                    vec![Value::Array(ValueType::U8, vec![Value::U8(9)])],
                ),
            )
            .build();
        let gguf = Gguf::parse(&bytes).unwrap();
        assert_eq!(gguf.metadata().len(), 14);
    }

    #[test]
    fn raw_metadata_allows_malformed_payloads() {
        let bytes = Builder::new()
            .metadata_raw("flag", ValueType::Bool.id(), vec![2])
            .build();
        assert!(Gguf::parse(&bytes).is_err());
    }
}
